{"path": "dominoes.py", "content": "def can_chain(dominoes):
    """Return a list of stones forming a closed domino chain, or None."""
    stones = [tuple(stone) for stone in dominoes]
    if not stones:
        return []

    used = [False] * len(stones)
    chain = [stones[0]]
    used[0] = True

    def search(end):
        if len(chain) == len(stones):
            return chain[0][0] == end
        tried = set()
        for i, (a, b) in enumerate(stones):
            if used[i] or (a, b) in tried:
                continue
            tried.add((a, b))
            if a == end:
                oriented = (a, b)
            elif b == end:
                oriented = (b, a)
            else:
                continue
            used[i] = True
            chain.append(oriented)
            if search(oriented[1]):
                return True
            chain.pop()
            used[i] = False
        return False

    return list(chain) if search(stones[0][1]) else None
"}

